node -e "
const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';
const sender = 'alice';
const recipient = 'bob';
const subject = 'High Priority: Onboarding Equipment Setup Needed';
const content = \`Hello Bob,

I'm writing to follow up on an onboarding equipment setup request, as outlined in Olivia's message to Ethan.

We have a newly onboarded contractor starting soon and need the following arranged before start of business on the next business day:

1. Standard Windows laptop — provisioned and ready for use
2. VPN access — configured and credentials provided
3. Email account — set up and operational

Please prioritize this request and confirm that a setup ticket is being tracked so we can ensure everything is in place ahead of the contractor's start.

Thank you for your prompt attention to this.

Best regards,
Alice\`;

// Build the .eml content (RFC 2822 format)
const eml = [
  'From: alice@example.com',
  'To: bob@example.com',
  'Subject: ' + subject,
  'Content-Type: text/plain; charset=\"utf-8\"',
  'Content-Transfer-Encoding: 7bit',
  'MIME-Version: 1.0',
  '',
  content
].join('\r\n');

// Ensure directories exist
for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, eml);
}

console.log('Successfully sent email to bob@example.com');
"
